package io.baozhu.atlas.execution; import io.baozhu.atlas.domain.TaskType; import org.springframework.stereotype.Component; import java.util.*;
@Component public class TaskExecutorRegistry { private final Map<TaskType,TaskExecutor> executors; public TaskExecutorRegistry(List<TaskExecutor> list){Map<TaskType,TaskExecutor> m=new EnumMap<>(TaskType.class);list.forEach(e->m.put(e.supports(),e));this.executors=Map.copyOf(m);} public TaskExecutor get(TaskType type){return executors.getOrDefault(type,new DefaultExecutor(type));}
 private record DefaultExecutor(TaskType type) implements TaskExecutor { public TaskExecutionResult execute(TaskExecutionContext context){long rows=Long.parseLong(context.task().config().getOrDefault("rows","1"));return new TaskExecutionResult(rows,rows,type+" task completed");} public TaskType supports(){return type;} } }
